import sizes from "@/content/media-sizes.json";

export type Photo = { src: string; w: number; h: number; caption?: string };

const table: Record<string, number[]> = sizes;

/**
 * Attach the intrinsic size of a prepared photo (generated by scripts/prepare-media.mjs). A file chosen
 * in the admin that was not prepared gets a 4:3 placeholder size rather than breaking the page; uploads
 * (stage 5) will record real sizes.
 */
export function photo(src: string, caption?: string): Photo {
  const size = table[src] ?? [1600, 1200];
  return { src, w: size[0], h: size[1], caption };
}

export const photos = (srcs: string[]) => srcs.map((s) => photo(s));
